export const BLOG_SLUGS = BLOG_POSTS.map((post) => post.slug);

export function isBlogSlug(slug: string) {
  return BLOG_SLUGS.includes(slug);
}

export function getBlogPostBySlug(slug: string) {
  return BLOG_POSTS.find((post) => post.slug === slug);
}

export function getBlogPostsForPage(pageNumber: 1 | 2) {
  return BLOG_POSTS.filter((post) => post.listingPage === pageNumber);
}

export function getBlogListingPageForSlug(slug: string): 1 | 2 {
  return getBlogPostBySlug(slug)?.listingPage ?? 1;
}

export function getBlogListingHref(pageNumber: 1 | 2, basePath: '/doctors-blog') {
  return pageNumber === 1 ? basePath : `${basePath}/2`;
}
